import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { attempt } from "./src/util/attempt.js";
import { delay } from "./src/promise/delay.js";
{
{
{
const [error, result] = attempt(async () => {
            await delay(100);
            throw new Error('test');
        });
        expect(error).toBeNull();
        try {
            await result;
        }
        catch (tryError) {
            expect(tryError).toBeInstanceOf(Error);
            expect(error).toBeNull();
        }
}
}
}
